INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4400991101010111, ARRAY['"A student has 14 study headings and must sort them into the conventional Caturdaśa-Vidyāsthāna scheme. Which composition should guide the first pass?"'::jsonb, '"A report compares an irrigation canal, a rainwater harvesting structure and a town plan. Which source-area grouping best supports the comparison?"'::jsonb, '"A student finds a claim that Sanskrit word structure may help computational language analysis. Which evaluation is most appropriate?"'::jsonb, '"A class compares Karma and rebirth with Moksha. Which relationship is the most appropriate high-level summary of the syllabus topics?"'::jsonb, '"A report combines ancient mathematics and astronomy but has only evidence about one calendar. How should the claim be narrowed?"'::jsonb, '"Which comparison best distinguishes Yajurveda and Samaveda in a basic Veda overview?"'::jsonb, '"A local-history project considers water management and trade connections. Which pair of topics fits the syllabus?"'::jsonb, '"A team describes a site as showing ''urban planning'' but gives only a photograph with no scale, date or site context. What is the main limitation?"'::jsonb, '"An ethical-living presentation needs to include duty, prosperity, enjoyment and liberation. What structure avoids omitting any Purushartha?"'::jsonb, '"A student''s notes define Jyotisha as poetic metre and Chandas as calendar study. Which correction is needed?"'::jsonb]::jsonb[], ARRAY['"Four Vedas, six Vedangas, and four additional branches such as Mimamsa, Nyaya, Purana and Dharmashastra"'::jsonb, '"Four Ashramas, four Purusharthas and six metals"'::jsonb, '"Four Vedas plus ten types of architecture only"'::jsonb, '"Four forms of HTML and ten CSS selectors"'::jsonb, '"Water management and architecture/planning within the technology unit"'::jsonb, '"Only language sciences"'::jsonb, '"Only the Purusharthas"'::jsonb, '"Only astronomy calendars"'::jsonb, '"It aligns with the syllabus topic, but a specific computational performance claim still needs evidence"'::jsonb, '"It proves every NLP system requires Sanskrit"'::jsonb, '"It is unrelated because computation never uses language structure"'::jsonb, '"It establishes a metalworking technique"'::jsonb, '"Karma and rebirth concern action and continuing existence; Moksha concerns liberation"'::jsonb, '"They are all names for poetic metre"'::jsonb, '"Moksha is a measurement of weight"'::jsonb, '"Karma is a computer peripheral"'::jsonb, '"State what the examined calendar demonstrates and avoid claiming it represents every tradition or period"'::jsonb, '"Claim every historical calendar followed it"'::jsonb, '"Remove the evidence and assert universality"'::jsonb, '"Classify the calendar as a Veda"'::jsonb, '"Yajurveda is associated with ritual formulas; Samaveda with chants/melodies"'::jsonb, '"Yajurveda is metre; Samaveda is grammar"'::jsonb, '"Yajurveda is a Purana; Samaveda is a Vedanga"'::jsonb, '"Both are types of temple architecture"'::jsonb, '"Irrigation/water management and transportation/trading techniques"'::jsonb, '"Shiksha and Chandas"'::jsonb, '"Brahmacharya and Sannyasa"'::jsonb, '"Inline and external CSS"'::jsonb, '"The evidence is insufficient to support a detailed historical interpretation"'::jsonb, '"The photo proves the site''s exact date"'::jsonb, '"Urban planning is not a syllabus topic"'::jsonb, '"A photograph alone gives all design rules"'::jsonb, '"Dharma, Artha, Kama and Moksha"'::jsonb, '"Rigveda, Samaveda, Chandas and Kalpa"'::jsonb, '"Brahmacharya, Grihastha, Nyaya and Vastu"'::jsonb, '"Time, distance, weight and calendars"'::jsonb, '"Jyotisha relates to astronomy/timekeeping; Chandas studies metre"'::jsonb, '"Jyotisha is grammar; Chandas is metalworking"'::jsonb, '"Jyotisha is a Veda; Chandas is a Purana"'::jsonb, '"Both concern CSS positioning"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4400991101010112, ARRAY['"A case study tries to show that a particular reservoir reflects historical water-management knowledge. What is the strongest evidence plan?"'::jsonb, '"A student wants to compare four Vedas, six Vedangas and four other branches without mixing categories. What is the correct count check?"'::jsonb, '"A presentation links traditional measurement with modern scientific units. Which method is strongest?"'::jsonb, '"A team is asked to discuss a temple''s form through the syllabus''s architecture themes. Which topics are most directly relevant?"'::jsonb, '"An argument claims Moksha is simply a synonym for material prosperity. What is the best correction?"'::jsonb, '"A researcher has evidence about textile dyeing from one site but wants to describe all ancient India. What wording is best?"'::jsonb, '"A student must describe the life-stage model but accidentally includes Dharma, Artha, Kama and Moksha. What is the correction?"'::jsonb, '"A project compares the role of calendars with agriculture-related star knowledge. What is the most relevant topic pair?"'::jsonb, '"A student wants to distinguish a supported syllabus fact from a historical hypothesis. Which practice is best?"'::jsonb, '"Which conclusion best reflects the full range of the BKS course described in the source?"'::jsonb]::jsonb[], ARRAY['"Combine site-specific records or credible studies with analysis of storage, supply and setting"'::jsonb, '"Use only the modern name of the reservoir"'::jsonb, '"Assume every reservoir belongs to the same tradition"'::jsonb, '"Infer details solely from the general syllabus"'::jsonb, '"4+6+4=14"'::jsonb, '"4+4+4=12"'::jsonb, '"6+6+4=16"'::jsonb, '"4×6=24"'::jsonb, '"Define each unit, identify its historical/source context and state any conversion assumptions"'::jsonb, '"Treat every historical unit as exactly one modern unit without evidence"'::jsonb, '"Ignore whether units measure time, distance or weight"'::jsonb, '"Use only a calendar illustration"'::jsonb, '"Vastu Shastra, civil architecture and temple architecture"'::jsonb, '"NLP, HTML forms and email signatures"'::jsonb, '"HCF, LCM and polynomial identities"'::jsonb, '"Recycle Bin and shell commands"'::jsonb, '"Moksha refers to liberation; Artha is the Purushartha associated with material means"'::jsonb, '"Moksha is grammar and Artha is metre"'::jsonb, '"Both are Vedas"'::jsonb, '"Both are units of distance"'::jsonb, '"This site provides an example of textile dyeing practice; broader prevalence needs additional evidence"'::jsonb, '"All places used precisely the same technique"'::jsonb, '"The site proves a universal rule"'::jsonb, '"Textile dyeing is a Purushartha"'::jsonb, '"Those are Purusharthas; Ashramas are Brahmacharya, Grihastha, Vanaprastha and Sannyasa"'::jsonb, '"Those are all Vedangas"'::jsonb, '"The two lists are identical"'::jsonb, '"Ashramas name the four Vedas"'::jsonb, '"Vedanga Jyotish/time-calendar and Nakshatrara Gyaan/agriculture"'::jsonb, '"Vyakarana and textile dyeing"'::jsonb, '"Karma and CPU memory"'::jsonb, '"Purana and CSS shadows"'::jsonb, '"Label the syllabus fact clearly and cite independent, case-specific evidence for the hypothesis"'::jsonb, '"Treat every hypothesis as verified because it fits the theme"'::jsonb, '"Remove all source notes"'::jsonb, '"Use confidence of wording as evidence"'::jsonb, '"It spans textual and philosophical traditions, science/mathematics and technology/architecture"'::jsonb, '"It is limited to rituals and excludes scientific topics"'::jsonb, '"It is only a construction course"'::jsonb, '"It is only a language grammar course"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb, '0'::jsonb]::jsonb[]);
